fn sqlite_snapshot_mp4_actual_erased_capability_preserves_binary_and_text(){use {semio_framework_artifact_reference::ArtifactDialect,semio_framework_os_kernel::io::IoPayload,semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding};let snapshot=fixture();let codec=(crate::native_codecs()[0].codec)();let provider=codec.snapshot_sqlite.as_ref().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.stdio.mp4".into(),standard:"isobmff".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(<Mp4Snapshot as store::ArtifactPack>::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(<Mp4Snapshot as store::ArtifactDsl>::print_dsl(&snapshot))};let database=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=(provider.import)(&codec.schema,&dialect,import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(match restored{IoPayload::Binary(bytes)=><Mp4Snapshot as store::ArtifactPack>::decode_pack(&bytes).unwrap(),IoPayload::Text(text)=><Mp4Snapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap()},snapshot);}}
