#[test]
fn sqlite_snapshot_mp4_native_and_typescript_exchange_complete_neutral_databases(){use std::{io::Write,process::{Command,Stdio},path::PathBuf};let snapshot=fixture();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let native=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let artifact=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../../🧬️schema/📸️snapshot/🟦️.ts");let artifact=std::fs::canonicalize(artifact).unwrap();let snapshot_root=artifact.parent().unwrap().join("🏅️standards/🔖️isobmff/🪆️subsets/✳️any/🧬️schema/📸️snapshot");let physical=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts");let physical=std::fs::canonicalize(physical).unwrap();let script=format!("import assert from'node:assert/strict';const api=await import({});const physical=await import({});const snapshot=api.parseMp4Snapshot(await Bun.file({}).json());const native=await physical.importSqliteDatabase(new Uint8Array(await Bun.stdin.arrayBuffer()));assert.deepEqual(await api.mp4SnapshotFromSqliteDatabase(native),snapshot);const database=await api.mp4SnapshotToSqliteDatabase(snapshot);assert.deepEqual(database,native);await Bun.write(Bun.stdout,await physical.exportSqliteDatabase(database));",serde_json::to_string(&artifact.to_string_lossy()).unwrap(),serde_json::to_string(&physical.to_string_lossy()).unwrap(),serde_json::to_string(&snapshot_root.join("🧫️fixtures/🪶️sqlite/🔣️.json").to_string_lossy()).unwrap());let mut child=Command::new("bun").args(["-e",&script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&native).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let typescript=import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(typescript,database);assert_eq!(Mp4Snapshot::from_sqlite_database(&typescript,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),snapshot);}

#[test]
fn sqlite_snapshot_mp4_owned_encoding_admits_exact_physical_bounds_and_controls_owned_copies(){
 use semio_framework_os_kernel::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotPhase};
 let snapshot=fixture();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let output=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let physical=match &output{store::io_schema::IoPayload::Binary(bytes)=>bytes.len(),store::io_schema::IoPayload::Text(text)=>text.len()};
  assert_eq!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:physical,..SqliteDatabaseLimits::default()})).unwrap(),output);
  if encoding==SnapshotEncoding::Binary{assert!(physical<1024);assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).is_ok());}
  let mut phases=Vec::new();let error=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut|event|{phases.push(event.phase);true},SqliteDatabaseLimits{max_file_bytes:physical-1,..SqliteDatabaseLimits::default()})).unwrap_err();assert_eq!(error.kind,semio_framework_os_kernel::sqlite_snapshot::ValueRefusalKind::OwnershipLimit);assert!(phases.contains(&SqliteSnapshotPhase::EncodeNative));
  let mut large=snapshot.clone();large.tracks[0].samples[0].data=vec![255;131073];let mut reached=false;assert!(large.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut|event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>0{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);
 }
}
